'use client';

/* TextInput — 输入框（源自 PixCreate 面板 ControlInput 的独立化组件）
 * 幽灵轨道样式：标签嵌左、输入嵌右（等宽字体右对齐）
 * 三态：hover=白色半透明亮底 / 聚焦=激活态（亮底+顶部高光）/ 禁用=35% 透明
 * 效率控件原则：中性灰白，不携带品牌色 */
import { useRef, useState } from 'react';
import './TextInput.css';

export interface TextInputProps {
  label?: string;
  value?: string;
  onChange?: (value: string) => void;
  placeholder?: string;
  maxLength?: number;
  isDisabled?: boolean;
}

export default function TextInput({
  label = '',
  value = '',
  onChange,
  placeholder = '',
  maxLength,
  isDisabled = false
}: TextInputProps) {
  const [focused, setFocused] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  return (
    <div
      className="it-field"
      data-focus={focused ? 'true' : 'false'}
      data-disabled={isDisabled ? 'true' : 'false'}
      onClick={() => inputRef.current?.focus()}
    >
      <span className="it-label">{label}</span>
      <input
        ref={inputRef}
        className="it-input"
        type="text"
        value={value}
        placeholder={placeholder}
        maxLength={maxLength}
        disabled={isDisabled}
        aria-label={label || undefined}
        onChange={e => onChange?.(e.target.value)}
        onFocus={() => setFocused(true)}
        onBlur={() => setFocused(false)}
      />
    </div>
  );
}

/* TextInput — 效率控件：中性灰白，三态 v3（hover 亮底 / 聚焦激活态 / 禁用） */
.it-field {
  position: relative;
  display: flex;
  align-items: center;
  width: 100%;
  height: var(--control-md);
  padding: 0 var(--space-l);
  border: none;
  border-radius: var(--radius-s);
  background: var(--color-hover-overlay);
  outline: none;
  cursor: text; /* 整行热区：点哪都聚焦输入 */
  user-select: none;
  transition: background-color var(--transition-fast), box-shadow var(--transition-fast);
}

.it-field:hover:not([data-disabled='true']) {
  background: rgba(255, 255, 255, 0.09); /* hover 白色半透明 */
}

/* 聚焦 = 激活态：叠亮底 + 顶部高光（三态 v3） */
.it-field[data-focus='true'] {
  background: rgba(255, 255, 255, 0.09);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

.it-field[data-disabled='true'] {
  opacity: 0.35;
  cursor: not-allowed;
}

.it-label {
  cursor: text;
  white-space: nowrap;
  color: var(--color-text-muted);
  font-size: var(--text-sm);
  font-weight: 500;
  letter-spacing: 0.01em;
  pointer-events: none;
}

.it-input {
  margin-left: auto;
  width: 55%;
  background: transparent;
  border: none;
  outline: none;
  text-align: right;
  font-family: var(--font-mono);
  font-size: var(--text-sm);
  color: var(--color-text-primary);
  caret-color: var(--color-text-primary);
}

.it-input::placeholder {
  color: var(--color-text-muted);
  opacity: 0.6;
}
